import os
from typing import Any, Dict, List, Optional

import boto3


class TextractLayoutExtractor:
    def __init__(
        self,
        region_name: Optional[str] = None,
        aws_access_key_id: Optional[str] = None,
        aws_secret_access_key: Optional[str] = None,
        aws_session_token: Optional[str] = None,
    ) -> None:
        self.client = boto3.client(
            "textract",
            region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
            aws_access_key_id=aws_access_key_id or os.getenv("AWS_ACCESS_KEY_ID"),
            aws_secret_access_key=aws_secret_access_key or os.getenv("AWS_SECRET_ACCESS_KEY"),
            aws_session_token=aws_session_token or os.getenv("AWS_SESSION_TOKEN"),
        )

    def analyze_document(
        self,
        *,
        file_path: Optional[str] = None,
        file_bytes: Optional[bytes] = None,
        s3_bucket: Optional[str] = None,
        s3_key: Optional[str] = None,
        feature_types: Optional[List[str]] = None,
    ) -> Dict[str, Any]:
        if not any([file_path, file_bytes, s3_bucket and s3_key]):
            raise ValueError("Provide file_path, file_bytes, or both s3_bucket and s3_key.")

        if file_path:
            with open(file_path, "rb") as f:
                file_bytes = f.read()

        document: Dict[str, Any]
        if file_bytes is not None:
            document = {"Bytes": file_bytes}
        else:
            document = {"S3Object": {"Bucket": s3_bucket, "Name": s3_key}}

        response = self.client.analyze_document(
            Document=document,
            FeatureTypes=feature_types or ["TABLES", "FORMS", "LAYOUT"],
        )
        return self._parse_response(response)

    def detect_text(
        self,
        *,
        file_path: Optional[str] = None,
        file_bytes: Optional[bytes] = None,
        s3_bucket: Optional[str] = None,
        s3_key: Optional[str] = None,
    ) -> Dict[str, Any]:
        if not any([file_path, file_bytes, s3_bucket and s3_key]):
            raise ValueError("Provide file_path, file_bytes, or both s3_bucket and s3_key.")

        if file_path:
            with open(file_path, "rb") as f:
                file_bytes = f.read()

        document: Dict[str, Any]
        if file_bytes is not None:
            document = {"Bytes": file_bytes}
        else:
            document = {"S3Object": {"Bucket": s3_bucket, "Name": s3_key}}

        response = self.client.detect_document_text(Document=document)
        return self._parse_response(response)

    def _parse_response(self, response: Dict[str, Any]) -> Dict[str, Any]:
        blocks = response.get("Blocks", [])
        by_id = {b["Id"]: b for b in blocks if "Id" in b}

        pages: Dict[int, Dict[str, Any]] = {}
        lines: List[Dict[str, Any]] = []
        words: List[Dict[str, Any]] = []
        tables: List[Dict[str, Any]] = []
        forms: List[Dict[str, Any]] = []
        layout: List[Dict[str, Any]] = []

        for block in blocks:
            page_num = block.get("Page", 1)
            pages.setdefault(
                page_num,
                {
                    "page": page_num,
                    "blocks": [],
                    "lines": [],
                    "tables": [],
                    "forms": [],
                    "layout": [],
                },
            )
            pages[page_num]["blocks"].append(block)

            block_type = block.get("BlockType")
            if block_type == "LINE":
                item = self._text_block(block)
                lines.append(item)
                pages[page_num]["lines"].append(item)
            elif block_type == "WORD":
                words.append(self._text_block(block))
            elif block_type == "TABLE":
                item = self._table_block(block, by_id)
                tables.append(item)
                pages[page_num]["tables"].append(item)
            elif block_type == "KEY_VALUE_SET":
                if "KEY" in block.get("EntityTypes", []):
                    item = self._form_field(block, by_id)
                    forms.append(item)
                    pages[page_num]["forms"].append(item)
            elif block_type and block_type.startswith("LAYOUT_"):
                item = self._layout_block(block, by_id)
                layout.append(item)
                pages[page_num]["layout"].append(item)

        return {
            "document_metadata": response.get("DocumentMetadata", {}),
            "pages": [pages[p] for p in sorted(pages)],
            "lines": lines,
            "words": words,
            "tables": tables,
            "forms": forms,
            "layout": layout,
            "raw": response,
        }

    def _text_block(self, block: Dict[str, Any]) -> Dict[str, Any]:
        return {
            "id": block.get("Id"),
            "type": block.get("BlockType"),
            "text": block.get("Text", ""),
            "confidence": block.get("Confidence"),
            "page": block.get("Page"),
            "geometry": block.get("Geometry", {}),
        }

    def _layout_block(self, block: Dict[str, Any], by_id: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
        child_text = self._collect_child_text(block, by_id)
        return {
            "id": block.get("Id"),
            "type": block.get("BlockType"),
            "text": child_text,
            "confidence": block.get("Confidence"),
            "page": block.get("Page"),
            "geometry": block.get("Geometry", {}),
            "reading_order": block.get("ReadingOrder"),
        }

    def _table_block(self, block: Dict[str, Any], by_id: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
        cells = []
        rows: Dict[int, Dict[int, str]] = {}

        for rel in block.get("Relationships", []):
            if rel.get("Type") != "CHILD":
                continue
            for child_id in rel.get("Ids", []):
                child = by_id.get(child_id)
                if not child or child.get("BlockType") != "CELL":
                    continue
                cell_text = self._collect_child_text(child, by_id)
                row_idx = child.get("RowIndex")
                col_idx = child.get("ColumnIndex")
                cells.append(
                    {
                        "id": child.get("Id"),
                        "row_index": row_idx,
                        "column_index": col_idx,
                        "row_span": child.get("RowSpan", 1),
                        "column_span": child.get("ColumnSpan", 1),
                        "text": cell_text,
                        "confidence": child.get("Confidence"),
                        "geometry": child.get("Geometry", {}),
                    }
                )
                if row_idx is not None and col_idx is not None:
                    rows.setdefault(row_idx, {})[col_idx] = cell_text

        matrix = []
        for row_idx in sorted(rows):
            row = rows[row_idx]
            matrix.append([row[col_idx] for col_idx in sorted(row)])

        return {
            "id": block.get("Id"),
            "type": "TABLE",
            "page": block.get("Page"),
            "confidence": block.get("Confidence"),
            "geometry": block.get("Geometry", {}),
            "cells": cells,
            "rows": matrix,
        }

    def _form_field(self, key_block: Dict[str, Any], by_id: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
        key_text = self._collect_child_text(key_block, by_id)
        value_texts = []
        value_blocks = []

        for rel in key_block.get("Relationships", []):
            if rel.get("Type") != "VALUE":
                continue
            for value_id in rel.get("Ids", []):
                value_block = by_id.get(value_id)
                if not value_block:
                    continue
                value_blocks.append(value_block)
                value_texts.append(self._collect_child_text(value_block, by_id))

        return {
            "id": key_block.get("Id"),
            "key": key_text,
            "value": " ".join(t for t in value_texts if t).strip(),
            "page": key_block.get("Page"),
            "confidence": key_block.get("Confidence"),
            "geometry": key_block.get("Geometry", {}),
            "value_geometry": [vb.get("Geometry", {}) for vb in value_blocks],
        }

    def _collect_child_text(self, block: Dict[str, Any], by_id: Dict[str, Dict[str, Any]]) -> str:
        parts: List[str] = []
        for rel in block.get("Relationships", []):
            if rel.get("Type") != "CHILD":
                continue
            for child_id in rel.get("Ids", []):
                child = by_id.get(child_id)
                if not child:
                    continue
                block_type = child.get("BlockType")
                if block_type in {"WORD", "LINE"}:
                    text = child.get("Text", "")
                    if text:
                        parts.append(text)
                elif block_type == "SELECTION_ELEMENT":
                    status = child.get("SelectionStatus")
                    if status == "SELECTED":
                        parts.append("[X]")
                    elif status == "NOT_SELECTED":
                        parts.append("[ ]")
        return " ".join(parts).strip()
